const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** True until the hold elapses. At exactly `ORG_SLUG_HOLD_DAYS` the slug is released. */
export function isSlugHoldActive(
  retiredAt: string,
  now: Date = new Date(),
): boolean {
  const retiredMs = Date.parse(retiredAt);
  if (Number.isNaN(retiredMs)) return false;
  return now.getTime() < retiredMs + ORG_SLUG_HOLD_DAYS * MS_PER_DAY;
}

export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (row) return toOrganization(row);

  const retired = getDb()
    .select()
    .from(organizationRetiredSlugs)
    .where(eq(organizationRetiredSlugs.slug, slug))
    .all();

  const now = new Date();
  for (const hold of retired) {
    if (!isSlugHoldActive(hold.retiredAt, now)) continue;
    const org = getDb()
      .select()
      .from(organizations)
      .where(and(eq(organizations.id, hold.orgId), isNull(organizations.archivedAt)))
      .get();
    if (org) return toOrganization(org);
  }

  return null;
}

/**
 * A slug is free for `orgId` unless another workspace — live or deleted —
 * currently uses it, or another workspace still holds it retired. A slug this
 * workspace itself retired is free for it immediately.
 */
export async function isOrgSlugAvailable(
  slug: string,
  orgId: OrgId,
  now: Date = new Date(),
): Promise<boolean> {
  const holder = getDb()
    .select({ id: organizations.id })
    .from(organizations)
    .where(eq(organizations.slug, slug))
    .get();
  if (holder && holder.id !== orgId) return false;

  const retired = getDb()
    .select()
    .from(organizationRetiredSlugs)
    .where(eq(organizationRetiredSlugs.slug, slug))
    .all();

  return !retired.some(
    (hold) => hold.orgId !== orgId && isSlugHoldActive(hold.retiredAt, now),
  );
}

/**
 * Points `orgId` at `to`, retires `from`, and ends any retirement of `to`
 * that belonged to this workspace. Expired holds of `to` are dropped so the
 * slug can be stored again.
 */
export async function renameOrgSlug(
  orgId: OrgId,
  from: string,
  to: string,
): Promise<Organization> {
  if (from === to) {
    const current = await findOrgById(orgId);
    if (!current) throw new Error(`Organization ${orgId} not found`);
    return current;
  }

  if (!(await isOrgSlugAvailable(to, orgId))) {
    throw new InvalidSlugError(to, "is not available");
  }

  const retiredAt = toIsoTimestamp(new Date());
  const updatedAt = retiredAt;

  const row = getDb().transaction((tx) => {
    tx.delete(organizationRetiredSlugs)
      .where(eq(organizationRetiredSlugs.slug, to))
      .run();
    tx.delete(organizationRetiredSlugs)
      .where(eq(organizationRetiredSlugs.slug, from))
      .run();
    tx.insert(organizationRetiredSlugs)
      .values({ id: newId(), orgId, slug: from, retiredAt })
      .run();

    return tx
      .update(organizations)
      .set({ slug: to, updatedAt })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();
  });

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

