/**
 * Feeds `uniqueSlug()`; matching on the prefix keeps the scan small.
 * Current slugs (including deleted workspaces) and retired slugs still inside
 * the hold are taken. A released slug is absent, so creation may derive it.
 */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();

  const now = new Date();
  const held = getDb()
    .select({
      slug: organizationRetiredSlugs.slug,
      retiredAt: organizationRetiredSlugs.retiredAt,
    })
    .from(organizationRetiredSlugs)
    .where(like(organizationRetiredSlugs.slug, `${prefix}%`))
    .all()
    .filter((row) => isSlugHoldActive(row.retiredAt, now))
    .map((row) => row.slug);

  return [...rows.map((row) => row.slug), ...held];
}

