/**
 * Replaces the workspace URL with the exact slug the admin typed. A collision
 * is refused (never suffixed). The previous slug stays resolvable until its
 * hold ends. Renaming to the slug already stored changes nothing.
 */
export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));
  assertValidSlug(input.slug);

  const current = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (current.slug === input.slug) return current;

  if (!(await orgRepo.isOrgSlugAvailable(input.slug, input.orgId))) {
    throw new InvalidSlugError(input.slug, "is not available");
  }

  const updated = await orgRepo.renameOrgSlug(
    input.orgId,
    current.slug,
    input.slug,
  );

  await emit("organization.slug_changed", {
    ...actorEnvelope(actor),
    from: current.slug,
    to: updated.slug,
  });

  await record(input.orgId, "organization.slug_changed", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `Slug ${current.slug} → ${updated.slug}`,
    metadata: { from: current.slug, to: updated.slug },
  });

  return updated;
}

